import { readFile } from 'node:fs/promises';

// Mirror the metadata generated by Semantic Release; never synthesize a second version/date.
const repository = process.env.GITHUB_REPOSITORY;
const token = process.env.GITHUB_TOKEN;
const version = process.env.RELEASE_VERSION;
const content = await readFile('patches-bundle.json', 'utf8');
const metadata = JSON.parse(content);
if (!repository || !token || metadata.version !== version ||
    !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d$/.test(metadata.created_at)) {
  throw new Error('Generated release metadata has an invalid version or timestamp');
}
const asset = await fetch(metadata.download_url, { method: 'HEAD' });
if (!asset.ok) throw new Error(`Release asset is not public: HTTP ${asset.status}`);

async function api(path, method = 'GET', body) {
  const response = await fetch(`https://api.github.com/repos/${repository}/${path}`, {
    method,
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json', 'X-GitHub-Api-Version': '2022-11-28' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (!response.ok) throw new Error(`Metadata mirror ${method} ${path}: HTTP ${response.status}`);
  return response.json();
}
for (const branch of ['master', 'main', 'dev']) {
  const ref = await api(`git/ref/heads/${branch}`);
  const parent = await api(`git/commits/${ref.object.sha}`);
  const tree = await api('git/trees', 'POST', { base_tree: parent.tree.sha,
    tree: ['patches-bundle.json', 'patches-bundle-pre.json', `patches-bundle-${version}.json`]
      .map(path => ({ path, mode: '100644', type: 'blob', content })) });
  const commit = await api('git/commits', 'POST', {
    message: `chore: mirror generated release ${version} metadata [skip ci]`,
    tree: tree.sha, parents: [ref.object.sha],
  });
  await api(`git/refs/heads/${branch}`, 'PATCH', { sha: commit.sha, force: false });
  console.log(`Mirrored ${branch}: ${version}`);
}
